type Mode = 'fixed' | 'sliding'

interface Options {
  max: number
  windowMs: number
  mode: Mode
  now?: () => number
}

interface Bucket {
  windowStart: number
  count: number
}

export class RateLimiter {
  private readonly max: number
  private readonly windowMs: number
  private readonly mode: Mode
  private readonly now: () => number
  private readonly buckets = new Map<string, Bucket>()
  private readonly timestamps = new Map<string, number[]>()

  constructor(opts: Options) {
    this.max = opts.max
    this.windowMs = opts.windowMs
    this.mode = opts.mode
    this.now = opts.now ?? Date.now
  }

  allow(key: string): boolean {
    const t = this.now()
    if (this.mode === 'sliding') return this.allowSliding(key, t)
    return this.allowFixed(key, t)
  }

  private allowFixed(key: string, t: number): boolean {
    const windowStart = Math.floor(t / this.windowMs) * this.windowMs
    const bucket = this.buckets.get(key)
    if (!bucket || bucket.windowStart !== windowStart) {
      this.buckets.set(key, { windowStart, count: 1 })
      return true
    }
    if (bucket.count >= this.max) return false
    bucket.count++
    return true
  }

  private allowSliding(key: string, t: number): boolean {
    const cutoff = t - this.windowMs
    let stamps = this.timestamps.get(key)
    if (!stamps) {
      stamps = []
      this.timestamps.set(key, stamps)
    }
    while (stamps.length > 0 && stamps[0] <= cutoff) stamps.shift()
    if (stamps.length >= this.max) return false
    stamps.push(t)
    return true
  }
}

import { describe, it, expect } from 'vitest'
import { RateLimiter } from '../src/rate-limiter'

describe('RateLimiter', () => {
  describe('fixed mode', () => {
    it('allows a request when under the max', () => {
      const limiter = new RateLimiter({ max: 5, windowMs: 1000, mode: 'fixed' })
      expect(limiter.allow('user-1')).toBe(true)
    })

    it('denies the request after max requests in the same window', () => {
      const limiter = new RateLimiter({ max: 5, windowMs: 1000, mode: 'fixed' })
      for (let i = 0; i < 5; i++) limiter.allow('user-1')
      expect(limiter.allow('user-1')).toBe(false)
    })

    it('tracks separate keys independently', () => {
      const limiter = new RateLimiter({ max: 2, windowMs: 1000, mode: 'fixed' })
      limiter.allow('a')
      limiter.allow('a')
      expect(limiter.allow('a')).toBe(false)
      expect(limiter.allow('b')).toBe(true)
    })

    it('resets capacity at the next window boundary', () => {
      let now = 0
      const limiter = new RateLimiter({
        max: 2,
        windowMs: 1000,
        mode: 'fixed',
        now: () => now,
      })
      limiter.allow('a')
      limiter.allow('a')
      expect(limiter.allow('a')).toBe(false)
      now = 1000
      expect(limiter.allow('a')).toBe(true)
    })
  })

  describe('sliding mode', () => {
    it('denies a call when prior requests still fall in the trailing window', () => {
      let now = 999
      const limiter = new RateLimiter({
        max: 5,
        windowMs: 1000,
        mode: 'sliding',
        now: () => now,
      })
      for (let i = 0; i < 5; i++) limiter.allow('a')
      now = 1500
      expect(limiter.allow('a')).toBe(false)
    })

    it('allows a call once the oldest request ages out', () => {
      let now = 0
      const limiter = new RateLimiter({
        max: 5,
        windowMs: 1000,
        mode: 'sliding',
        now: () => now,
      })
      for (let i = 0; i < 5; i++) limiter.allow('a')
      now = 500
      expect(limiter.allow('a')).toBe(false)
      now = 1100
      expect(limiter.allow('a')).toBe(true)
    })

    it('tracks separate keys independently in sliding mode', () => {
      const limiter = new RateLimiter({
        max: 2,
        windowMs: 1000,
        mode: 'sliding',
      })
      limiter.allow('a')
      limiter.allow('a')
      expect(limiter.allow('a')).toBe(false)
      expect(limiter.allow('b')).toBe(true)
    })
  })
})

